import React, { useState, useEffect, useRef } from 'react';
import { runMAS, getUserRuns } from '../api';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar } from 'recharts';
import './UserDashboard.css';

function UserDashboard({ user, onLogout }) {
  const [messages, setMessages] = useState([
    { type: 'bot', text: 'Hello! I\'m your AgentMonitor assistant. Describe a coding task and I\'ll run the Multi-Agent System to help you!' }
  ]);
  const [inputMessage, setInputMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [currentResult, setCurrentResult] = useState(null);
  const [showEnhancedCode, setShowEnhancedCode] = useState(false);
  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = async () => {
    if (!inputMessage.trim() || loading) return;

    const userMessage = inputMessage.trim();
    setInputMessage('');

    // Add user message to chat
    setMessages(prev => [...prev, { type: 'user', text: userMessage }]);
    setLoading(true);

    // Add loading message
    setMessages(prev => [...prev, { type: 'bot', text: 'Running Multi-Agent System...', isLoading: true }]);

    try {
      const data = await runMAS(userMessage, '');
      
      // Remove loading message
      setMessages(prev => prev.filter(msg => !msg.isLoading));
      
      // Add success message
      setMessages(prev => [...prev, {
        type: 'bot',
        text: `✅ MAS execution completed! Predicted score: ${data.predicted_score.toFixed(2)}`,
        result: data
      }]);
      
      setCurrentResult(data);
      setShowEnhancedCode(false);
    } catch (err) {
      // Remove loading message
      setMessages(prev => prev.filter(msg => !msg.isLoading));
      
      // Add error message
      setMessages(prev => [...prev, {
        type: 'bot',
        text: `❌ Error: ${err.message}. Please try again.`,
        isError: true
      }]);
    } finally {
      setLoading(false);
    }
  };

  const handleEnhanceAgain = async () => {
    if (!currentResult || loading) return;

    setLoading(true);
    setMessages(prev => [...prev, { type: 'bot', text: 'Enhancing code with improved MAS configuration...', isLoading: true }]);

    try {
      const lastUserMessage = messages.filter(msg => msg.type === 'user').slice(-1)[0]?.text || '';
      const data = await runMAS(lastUserMessage, currentResult.result);
      
      setMessages(prev => prev.filter(msg => !msg.isLoading));
      setMessages(prev => [...prev, {
        type: 'bot',
        text: `✅ Enhanced! New predicted score: ${data.predicted_score.toFixed(2)} (Previous: ${currentResult.predicted_score.toFixed(2)})`,
        result: data
      }]);
      
      setCurrentResult(data);
      setShowEnhancedCode(true);
    } catch (err) {
      setMessages(prev => prev.filter(msg => !msg.isLoading));
      setMessages(prev => [...prev, {
        type: 'bot',
        text: `❌ Enhancement failed: ${err.message}`,
        isError: true
      }]);
    } finally {
      setLoading(false);
    }
  };

  const getFeatureChartData = (features) => {
    if (!features) return [];
    return Object.entries(features).map(([key, value]) => ({
      name: key.replace(/_/g, ' '),
      value: typeof value === 'number' ? value : 0
    }));
  };

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <h1>User Dashboard</h1>
        <div className="user-info">
          <span>Welcome, {user.username}</span>
          <button onClick={onLogout}>Logout</button>
        </div>
      </header>

      <div className="dashboard-content">
        <div className="submit-section">
          <h2>Submit New Task</h2>
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Task Description</label>
              <textarea
                value={task}
                onChange={(e) => setTask(e.target.value)}
                placeholder="Describe the coding task..."
                rows="4"
                required
              />
            </div>
            <div className="form-group">
              <label>Initial Code (Optional)</label>
              <textarea
                value={code}
                onChange={(e) => setCode(e.target.value)}
                placeholder="Provide initial code if any..."
                rows="6"
              />
            </div>
            <button type="submit" disabled={loading}>
              {loading ? 'Running MAS...' : 'Run MAS'}
            </button>
          </form>

          {result && (
            <div className="result-section">
              <h3>Result</h3>
              <div className="result-card">
                <p><strong>Run ID:</strong> {result.run_id}</p>
                <p><strong>Predicted Score:</strong> {result.predicted_score.toFixed(2)}</p>
                <h4>Features Visualization</h4>
                <ResponsiveContainer width="100%" height={300}>
                  <BarChart data={getFeatureChartData(result.features)}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="name" angle={-45} textAnchor="end" height={100} />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    <Bar dataKey="value" fill="#667eea" />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
          )}
        </div>

        <div className="runs-section">
          <h2>My Recent Runs</h2>
          <div className="runs-list">
            {runs.map((run) => (
              <div key={run._id} className="run-card" onClick={() => setSelectedRun(run)}>
                <p><strong>Task:</strong> {run.task.substring(0, 50)}...</p>
                <p><strong>Score:</strong> {run.predicted_score.toFixed(2)}</p>
                <p><strong>Date:</strong> {new Date(run.created_at).toLocaleString()}</p>
              </div>
            ))}
            {runs.length === 0 && <p className="no-runs">No runs yet</p>}
          </div>
        </div>
      </div>

      {selectedRun && (
        <div className="modal" onClick={() => setSelectedRun(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h3>Run Details</h3>
            <p><strong>Task:</strong> {selectedRun.task}</p>
            <p><strong>Predicted Score:</strong> {selectedRun.predicted_score.toFixed(2)}</p>
            <p><strong>Date:</strong> {new Date(selectedRun.created_at).toLocaleString()}</p>
            <h4>Features</h4>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={getFeatureChartData(selectedRun.features)}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" angle={-45} textAnchor="end" height={100} />
                <YAxis />
                <Tooltip />
                <Bar dataKey="value" fill="#667eea" />
              </BarChart>
            </ResponsiveContainer>
            <button onClick={() => setSelectedRun(null)}>Close</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default UserDashboard;
